/* رحلة الفصل إلى السماء — منطق اللعبة */

/* الصور المضمّنة (المنطاد وخلفية الرحلة) */
const ASSETS = {
  balloon: 'data:image/webp;base64,',
  bg: 'data:image/webp;base64,'
};
document.querySelectorAll('img[data-asset]').forEach(img => { img.src = ASSETS[img.dataset.asset]; });

/* ---------------- المحتوى القرآني ----------------
   سورة الملك برواية حفص بالرسم العثماني، مطابقة حرفًا وتشكيلًا لنص مجمع الملك فهد (الإصدار ١٣). */
const VERSES = [
 "تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ",
 "ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ",
 "ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ",
 "ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ",
 "وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ",
 "وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ",
 "إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ",
 "تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ",
 "قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ",
 "وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ",
 "فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ",
 "إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ",
 "وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ",
 "أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ",
 "هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ",
 "ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ",
 "أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ",
 "وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ",
 "أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ",
 "أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ",
 "أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ",
 "أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ",
 "قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ",
 "قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ",
 "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ",
 "قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ",
 "فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ",
 "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ",
 "قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ",
 "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ"
];
const LEVELS = [
  { name: 'المستوى الأول',  place: 'على المرج الأخضر' },
  { name: 'المستوى الثاني', place: 'عند سفح الجبل' },
  { name: 'المستوى الثالث', place: 'في منتصف الجبل' },
  { name: 'المستوى الرابع', place: 'فوق قمة الجبل' },
  { name: 'المستوى الخامس', place: 'تحت السحاب' },
  { name: 'المستوى السادس', place: 'فوق السحاب' },
];

(() => {
'use strict';
const N = 30, REPS = 5, KEY = 'classSkyOneScreen.v1';
const AR = n => String(n).replace(/\d/g, d => '٠١٢٣٤٥٦٧٨٩'[d]);
const $ = id => document.getElementById(id);
const lvOf = i => Math.floor(i / 5);
const SPRITE_AR = 653 / 1074;

/* ---------- state ---------- */
const fresh = () => ({ v: 1, name: '', i: 0, reps: 0, done: Array(N).fill(0), started: false, launched: false, finished: false, sound: true });
let S = fresh();
try {
  const d = JSON.parse(localStorage.getItem(KEY) || 'null');
  if (d && d.v === 1 && typeof d.name === 'string' && Number.isInteger(d.i) && d.i >= 0 && d.i < N && Number.isInteger(d.reps) && d.reps >= 0 && d.reps <= REPS && Array.isArray(d.done) && d.done.length === N)
    S = { ...fresh(), ...d, done: d.done.map(x => (x ? 1 : 0)) };
    if (typeof d.launched !== 'boolean') S.launched = d.i > 0 || d.reps > 0 || !!d.finished;
} catch (e) {}
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (e) {} };

/* ---------- sound ---------- */
let ac;
function tone(fs, gap = .12, dur = .5, vol = .07) {
  if (!S.sound) return;
  try {
    ac = ac || new (window.AudioContext || window.webkitAudioContext)(); const t = ac.currentTime;
    fs.forEach((f, k) => { const o = ac.createOscillator(), g = ac.createGain(); o.type = 'sine'; o.frequency.value = f;
      g.gain.setValueAtTime(0, t + k * gap); g.gain.linearRampToValueAtTime(vol, t + k * gap + .02); g.gain.exponentialRampToValueAtTime(.0001, t + k * gap + dur);
      o.connect(g).connect(ac.destination); o.start(t + k * gap); o.stop(t + k * gap + dur + .05); });
  } catch (e) {}
}
function soundIcon() {
  $('soundBtn').innerHTML = S.sound
    ? '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" stroke="currentColor" stroke-width="2" fill="none"/></svg>'
    : '<svg viewBox="0 0 24 24"><path d="M4 9h4l5-4v14l-5-4H4z"/><path d="M16 9l6 6M22 9l-6 6" stroke="currentColor" stroke-width="2"/></svg>';
  $('soundBtn').style.color = 'var(--text)';
  $('soundBtn').setAttribute('aria-label', S.sound ? 'إيقاف الصوت' : 'تشغيل الصوت');
}

/* ---------- geometry (recomputed on resize) ---------- */
let G = {};
let transit = false;
let inGame = false;   // في شاشة البداية لا تظهر أي سحابة آية
function geometry() {
  const W = innerWidth, H = innerHeight, land = W > H && W >= 700;
  const hudH = ($('hud').offsetHeight || 64) + 16, ctlH = ($('controls').offsetHeight || 150) + 16;
  const bh = land ? Math.min(H * .56, 470) : Math.max(170, Math.min(H * .31, 290));
  // صورة الخلفية الطويلة (١٠٢٤×١٥٣٦) بنسبتها الأصلية: ارتفاعها ٤ أضعاف الشاشة، وتغطي العرض دائمًا
  const imgH = Math.max(H * 4, W * 1.5), imgW = imgH / 1.5;
  G = { W, H, land, hudH, ctlH, bh, bw: bh * SPRITE_AR, imgH, imgW };
  G.base = imgH * .045;                          // المنطاد واقف على العشب في أسفل الصورة
  G.step = imgH * .8 / 30;                       // كل آية ترفع المنطاد جزءًا متساويًا من الرحلة حتى قرب الشمس
  G.want = land ? (H - bh) / 2 - ctlH * .25 : ctlH;
  G.top = altOf(30); G.worldH = imgH;
}
// ارتفاع محطة الآية i
const altOf = i => G.base + i * G.step;
// كل ترديد يرفع المنطاد قليلًا، والترديد الخامس يكمل الصعود إلى سحابة الآية التالية
const altP = () => (!inGame || !S.launched) ? altOf(0) : S.finished ? G.top + G.step * .3 : altOf(S.started ? S.i : 0) + Math.min(S.reps, REPS) * G.step * .17;
const camOf = alt => Math.max(0, Math.min(G.worldH - G.H, alt - G.want));
const balloonX = () => G.land ? G.W * .26 : G.W / 2;

/* ---------- scenery ---------- */
function scenery() {
  // الخلفية: صورة واحدة طويلة من العشب إلى الشمس، بلا تمدد، متمركزة أفقيًا
  const img = $('bgimg');
  Object.assign(img.style, { width: G.imgW + 'px', height: G.imgH + 'px', left: (G.W - G.imgW) / 2 + 'px' });
  $('sky').style.height = $('world').style.height = G.imgH + 'px';
}

/* ---------- station clouds ---------- */
const st = [];
function buildStations() {
  for (let i = 0; i < N; i++) {
    const c = document.createElement('div'); c.className = 'st';
    c.innerHTML = `<div class="tag">سورة الملك، الآية ${AR(i + 1)}</div><p class="ayah"><span></span><span class="num"> \u06DD${AR(i + 1)}</span></p><div class="badge">${AR(i + 1)}</div>`;
    c.querySelector('.ayah span').textContent = VERSES[i];
    $('world').append(c); st.push(c);
  }
}
function cloudBox(i) {
  // where the cloud of verse i sits when it is the active one
  const { W, H, land, bh, bw } = G;
  if (land) {
    const w = Math.min(W * .54, 820), cx = W * .67;
    return { w, left: cx - w / 2, bottom: altOf(i) + bh * .18, font: Math.max(26, Math.min(W * .032, 62)) };
  }
  const w = Math.min(W - 16, 640);
  return { w, left: (W - w) / 2, bottom: altOf(i) + bh + 6, font: Math.max(20, Math.min(W * .062, 36)) };
}
function layoutStations() {
  for (let i = 0; i < N; i++) {
    const c = st[i], b = cloudBox(i);
    c.style.width = b.w + 'px'; c.style.left = b.left + 'px'; c.style.bottom = b.bottom + 'px';
    const a = c.querySelector('.ayah'); a.style.fontSize = b.font + 'px';
    // keep the active cloud inside the free space between the top bar and the balloon
    const room = G.land ? G.H - G.hudH - G.ctlH - 10 : G.H - G.hudH - G.ctlH - G.bh - 12;
    let f = b.font; c.style.transform = 'none';
    while (c.offsetHeight > room && f > 16) { f -= 1; a.style.fontSize = f + 'px'; }
  }
  stationStates();
}
function stationStates() {
  for (let i = 0; i < N; i++) {
    const c = st[i], active = !transit && inGame && S.launched && i === S.i && S.started && !S.finished;
    c.classList.toggle('active', active); c.classList.toggle('done', !!S.done[i]); c.classList.toggle('future', !active && !S.done[i]);
    c.classList.toggle('far', !inGame || !S.launched || (!active && Math.abs(i - S.i) > 1));
    if (active) {                                   // الغيمة الحالية تصعد مع المنطاد وتبقى فوقه
      c.style.transform = 'none';
      c.style.bottom = (G.land ? altP() + G.bh * .18 : altP() + G.bh + 6) + 'px';
      continue;
    }
    c.style.bottom = cloudBox(i).bottom + 'px';
    // small cloud beside the path, alternating sides
    const side = i % 2 ? -1 : 1, w = c.offsetWidth || 300;
    const dx = side * (G.W / 2 - Math.min(70, G.W * .1)) - (parseFloat(c.style.left) + w / 2 - G.W / 2);
    const s = Math.min(.3, 150 / w);
    c.style.transform = `translate(${dx}px, ${-G.bh * .2}px) scale(${s})`;
  }
}

/* ---------- balloon + camera ---------- */
function placeBalloon(alt) {
  const b = $('balloon');
  Object.assign(b.style, { width: G.bw + 'px', height: G.bh + 'px', left: balloonX() - G.bw / 2 + 'px', bottom: alt + 'px' });
}
function camera(alt) {
  // الكاميرا تتبع المنطاد فتظهر الطبقة التالية من الصورة
  const c = camOf(alt);
  $('world').style.transform = $('sky').style.transform = `translateY(${c}px)`;
}

/* ---------- labels + HUD ---------- */
function fitLabel() {
  const l = $('label'); l.textContent = S.name; l.classList.toggle('empty', !S.name); l.style.fontSize = '';
  if (!S.name) return; let fs = parseFloat(getComputedStyle(l).fontSize);
  while (l.scrollWidth > l.clientWidth + 1 && fs > 7) { fs--; l.style.fontSize = fs + 'px'; }
}
function hud() {
  const lv = LEVELS[lvOf(S.i)]; $('lvName').textContent = lv.name; $('lvPlace').textContent = lv.place;
  $('of').textContent = `الآية ${AR(S.i + 1)} من ${AR(N)}`;
  const p = S.finished ? 1 : Math.min(1, (S.i + S.reps / REPS) / N);
  $('mini').style.right = `calc(${p} * (100% - 30px))`;   // المنطاد الصغير يتقدم نحو الشمس
  [...$('bar').querySelectorAll('.s')].forEach((s, k) => { s.classList.toggle('d', !!S.done[k]); s.classList.toggle('n', k === S.i && !S.done[k]); });
  $('backBtn').disabled = busy || !S.launched || (!S.finished && S.i === 0 && S.reps === 0);
  $('controls').classList.toggle('ready', !S.launched);
  $('cnt').textContent = `التكرار ${AR(S.reps)} من ${AR(REPS)}`;
  [...$('stars').children].forEach((s, k) => s.classList.toggle('lit', k < S.reps));
  $('rep').disabled = busy || S.reps >= REPS || S.finished;
}
let tt; function toast(m, ms = 1900) { const t = $('toast'); t.textContent = m; t.classList.add('show'); clearTimeout(tt); tt = setTimeout(() => t.classList.remove('show'), ms); }
function sparks() {
  const r = st[S.i].getBoundingClientRect(), b = $('sparks'); b.innerHTML = '';
  for (let k = 0; k < 14; k++) { const s = document.createElement('i'), a = k / 14 * Math.PI * 2;
    s.style.left = r.left + r.width / 2 + 'px'; s.style.top = r.top + r.height / 2 + 'px';
    s.style.setProperty('--dx', Math.cos(a) * (140 + Math.random() * 100) + 'px'); s.style.setProperty('--dy', Math.sin(a) * (90 + Math.random() * 60) + 'px'); b.append(s); }
}

/* ---------- game flow ---------- */
let busy = false, cool = false;
function rep() {
  if (busy || cool || S.finished || S.reps >= REPS || !S.started || !S.launched) return;
  cool = true; setTimeout(() => (cool = false), 400);
  S.reps++; save(); tone([784], 0, .35, .06); hud();
  if (S.reps < REPS) { placeBalloon(altP()); camera(altP()); stationStates(); }
  const star = $('stars').children[S.reps - 1]; star.classList.remove('lit'); void star.offsetWidth; star.classList.add('lit');
  if (S.reps === REPS) complete();
}
const dur = v => parseFloat(getComputedStyle(document.documentElement).getPropertyValue(v)) * 1000;
function complete() {
  busy = true; S.done[S.i] = 1; save(); hud();
  st[S.i].classList.add('glow'); sparks();
  const last = S.i === N - 1, lvEnd = (S.i + 1) % 5 === 0;
  if (last) { tone([523, 659, 784, 1047, 1319], .12, .8); toast('أحسنتم! أتممتم سورة الملك كاملة', 2400); }
  else if (lvEnd) { tone([523, 659, 784, 1047], .12, .7); toast(`أحسنتم! أتممتم ${LEVELS[lvOf(S.i)].name}، هيا نصعد إلى ${LEVELS[lvOf(S.i) + 1].name}`, 3600); }
  else { tone([659, 784, 988], .13, .6); toast('أحسنتم! لننتقل إلى الآية التالية'); }
  setTimeout(() => { st[S.i].classList.remove('glow'); ascend(last); }, 750);
}
function ascend(last) {
  const from = S.i, to = last ? from : from + 1;
  transit = true; st[from].classList.add('done');
  S.finished = last; stationStates();                 // الغيمة الحالية تصغر وتبتعد عن الطريق
  const alt = last ? G.top + G.step * .3 : altOf(to);
  setTimeout(() => { placeBalloon(alt); camera(alt); }, 150);
  setTimeout(() => {
    if (last) { save(); busy = false; transit = false; showEnd(); return; }
    S.i = to; S.reps = 0; save(); transit = false;      // التقدّم يُحفظ بعد وصول المنطاد
    stationStates(); hud();
    setTimeout(() => { busy = false; hud(); }, 450);    // الزر يعمل بعد ظهور الغيمة الجديدة كاملة
  }, 150 + Math.max(dur('--rise'), dur('--cam') + 100));
}
function showEnd() {
  $('controls').hidden = true; $('end').hidden = false; hud();
  const n = S.done.reduce((a, b) => a + b, 0);
  $('sum').textContent = n === N ? `فصل «${S.name}» ردّد الآيات الثلاثين، كل آية خمس مرات.` : `فصل «${S.name}» ردّد ${AR(n)} آية من ٣٠، كل آية خمس مرات.`;
  const f = $('fall'); f.innerHTML = '';
  if (!matchMedia('(prefers-reduced-motion: reduce)').matches) for (let k = 0; k < 24; k++) { const s = document.createElement('i'), z = 8 + Math.random() * 16;
    Object.assign(s.style, { left: Math.random() * 100 + '%', width: z + 'px', height: z + 'px', animationDuration: 6 + Math.random() * 7 + 's', animationDelay: -Math.random() * 12 + 's' }); f.append(s); }
}
function enterGame() {
  inGame = true;
  $('start').hidden = true; $('end').hidden = true; $('fall').innerHTML = '';
  $('hud').hidden = false; $('controls').hidden = S.finished;
  relayout(true);
  if (S.finished) { showEnd(); return; }
  if (S.reps >= REPS) { busy = true; hud(); setTimeout(() => { S.done[S.i] = 1; ascend(S.i === N - 1); }, 500); }
}
function showStart() {
  inGame = false;
  $('hud').hidden = true; $('controls').hidden = true; $('end').hidden = true; $('fall').innerHTML = '';
  $('start').hidden = false; $('cls').value = S.name; $('go').disabled = !S.name.trim();
  const r = $('resume'); r.hidden = !(S.started && !S.finished && S.name);
  r.textContent = `متابعة الرحلة (الآية ${AR(S.i + 1)})`;
  relayout(true);
}
function goBack() {
  if (busy || !inGame) return;
  if (S.finished) {                                   // من شاشة النهاية: نعود للآية الأخيرة
    S.finished = false; S.i = N - 1; S.done[N - 1] = 0;
    $('end').hidden = true; $('fall').innerHTML = ''; $('controls').hidden = false;
  } else if (S.i > 0) { S.i--; S.done[S.i] = 0; }
  else if (S.reps === 0) return;
  S.reps = 0; save();
  relayout(false);
  toast(`رجعنا إلى الآية ${AR(S.i + 1)}`, 1500);
}
function restart() { const name = S.name, sound = S.sound; S = fresh(); S.name = name; S.sound = sound; save(); showStart(); }

/* ---------- layout ---------- */
function relayout(instant) {
  const w = $('view'); if (instant) w.classList.add('instant');
  geometry(); scenery(); layoutStations();
  const alt = altP();
  placeBalloon(alt); camera(alt); fitLabel(); hud();
  if (instant) { void w.offsetWidth; requestAnimationFrame(() => w.classList.remove('instant')); }
}
let rt; addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(() => { if (!busy) relayout(true); }, 150); });

/* ---------- teacher settings ---------- */
function mrow(body, text, ...els) { const r = document.createElement('div'); r.className = 'mrow'; const p = document.createElement('p'); p.textContent = text; r.append(p);
  const l = document.createElement('div'); l.className = 'in'; l.append(...els); r.append(l); body.append(r); }
function mbtn(t, c, fn) { const b = document.createElement('button'); b.className = 'btn ' + c; b.textContent = t; b.onclick = fn; return b; }
function modal(build) { $('mbody').innerHTML = ''; build($('mbody')); $('modal').hidden = false; $('mclose').focus(); }
const closeM = () => ($('modal').hidden = true);
function settings() {
  modal(body => {
    const inp = document.createElement('input'); inp.value = S.name; inp.maxLength = 20; inp.setAttribute('aria-label', 'اسم الفصل');
    mrow(body, 'اسم الفصل على المنطاد', inp, mbtn('حفظ', 'soft', () => { const v = inp.value.trim(); if (!v) return; S.name = v; save(); fitLabel(); closeM(); }));
    const u = mbtn('تراجع عن آخر ترديد', 'soft', () => { if (busy || S.reps < 1) return; S.reps--; save(); hud(); placeBalloon(altP()); camera(altP()); stationStates(); closeM(); }); u.disabled = busy || S.reps < 1;
    mrow(body, 'إذا ضُغط زر «تم الترديد» بالخطأ', u);
    const sel = document.createElement('select'); sel.setAttribute('aria-label', 'اختيار الآية');
    for (let k = 0; k < N; k++) { const o = document.createElement('option'); o.value = k; o.textContent = `الآية ${AR(k + 1)} (${LEVELS[lvOf(k)].name})`; o.selected = k === S.i; sel.append(o); }
    mrow(body, 'البدء من آية أخرى (يبدأ التكرار من الصفر)', sel, mbtn('انتقال', 'soft', () => { if (busy) return; S.i = +sel.value; S.reps = 0; S.finished = false; save(); closeM(); enterGame(); }));
    mrow(body, 'إعادة الرحلة من الآية الأولى', mbtn('إعادة الرحلة', 'danger', () => { if (busy) return;
      modal(b2 => mrow(b2, 'سيُمسح التقدّم ويعود المنطاد إلى المرج. هل أنتِ متأكدة؟', mbtn('نعم، أعيدي الرحلة', 'danger', () => { closeM(); restart(); }), mbtn('تراجع', 'soft', closeM))); }));
  });
}

/* ---------- wiring ---------- */
for (let g = 0; g < 6; g++) { const d = document.createElement('div'); d.className = 'g'; for (let k = 0; k < 5; k++) { const s = document.createElement('div'); s.className = 's'; d.append(s); } $('bar').append(d); }
for (let k = 0; k < REPS; k++) $('stars').append(document.createElement('span'));
buildStations(); soundIcon();
$('cls').addEventListener('input', e => { const v = e.target.value.trim(); $('go').disabled = !v; S.name = v; fitLabel(); });
$('cls').addEventListener('keydown', e => { if (e.key === 'Enter' && !$('go').disabled) $('go').click(); });
$('go').onclick = () => { const v = $('cls').value.trim(); if (!v) return; const sound = S.sound; S = fresh(); S.name = v; S.sound = sound; S.started = true; save(); if (ac && ac.state === 'suspended') ac.resume(); enterGame(); };
$('resume').onclick = () => { save(); enterGame(); };
$('rep').onclick = rep;
$('soundBtn').onclick = () => { S.sound = !S.sound; save(); soundIcon(); };
$('setBtn').onclick = settings;
$('mclose').onclick = closeM;
$('modal').addEventListener('click', e => { if (e.target.id === 'modal') closeM(); });
addEventListener('keydown', e => { if (e.key === 'Escape') closeM(); });
$('again').onclick = restart;
$('backBtn').onclick = goBack;
$('homeBtn').onclick = () => { if (!busy) showStart(); };
$('launch').onclick = () => {                          // الآيات تظهر فقط بعد الضغط على «ابدأ»
  if (busy || S.launched) return;
  S.launched = true; save(); hud(); relayout(false);
  st[S.i].classList.add('glow'); setTimeout(() => st[S.i].classList.remove('glow'), 1100);
  tone([659, 784], .12, .5);
};
$('endX').onclick = () => { $('end').hidden = true; };   // إخفاء البطاقة ليظهر المنطاد عند الشمس؛ الإعادة متاحة من الإعدادات
const boot = () => { if (S.started && S.name) enterGame(); else showStart(); };
if (document.fonts) document.fonts.ready.then(boot); else boot();
})();
